import{_ as t,c as e,o,a3 as r}from"./chunks/framework.BusRvirq.js";const u=JSON.parse('{"title":"소프트웨어 개발 외주 용역 표준도급계약서","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/13_Subcontract_Agreement_template.html"}]]},"headers":[],"relativePath":"public/templates/13_Subcontract_Agreement_template.md","filePath":"public/templates/13_Subcontract_Agreement_template.md","lastUpdated":1790810085000}'),l={name:"public/templates/13_Subcontract_Agreement_template.md"};function c(n,a,i,p,_,h){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="소프트웨어-개발-외주-용역-표준도급계약서" tabindex="-1">소프트웨어 개발 외주 용역 표준도급계약서 <a class="header-anchor" href="#소프트웨어-개발-외주-용역-표준도급계약서" aria-label="Permalink to “소프트웨어 개발 외주 용역 표준도급계약서”">​</a></h1><p>주식회사 엠파시(이하 &quot;갑&quot;이라 한다)와 주식회사 [협력사명](이하 &quot;을&quot;이라 한다)은 [프로젝트명] 내 [외주 과업명](이하 &quot;본건 용역&quot;이라 한다)의 완성 및 납품을 위하여 다음과 같이 계약을 체결한다.</p><h3 id="제1조-목적-및-과업-범위" tabindex="-1">제1조 (목적 및 과업 범위) <a class="header-anchor" href="#제1조-목적-및-과업-범위" aria-label="Permalink to “제1조 (목적 및 과업 범위)”">​</a></h3><p>&quot;을&quot;은 별첨 &quot;외주 과업내용서(SOW)&quot;에 기재된 사양 및 일정에 따라 소프트웨어 개발 업무를 완성하여 &quot;갑&quot;에게 납품한다.</p><h3 id="제2조-대금-지급-조건" tabindex="-1">제2조 (대금 지급 조건) <a class="header-anchor" href="#제2조-대금-지급-조건" aria-label="Permalink to “제2조 (대금 지급 조건)”">​</a></h3><ol><li>선금(30%): 계약 체결 및 착수계 제출 시 지급.</li><li>잔금(70%): 산출물 최종 검수 합격 후 세금계산서 청구일로부터 14일 이내 지급.</li></ol><h3 id="제3조-지식재산권의-완전한-귀속" tabindex="-1">제3조 (지식재산권의 완전한 귀속) <a class="header-anchor" href="#제3조-지식재산권의-완전한-귀속" aria-label="Permalink to “제3조 (지식재산권의 완전한 귀속)”">​</a></h3><p>&quot;을&quot;이 본 계약에 따라 개발한 소스코드 및 모든 산출물의 저작재산권(2차적저작물작성권 포함)은 대금 지급과 동시에 &quot;갑&quot;에게 확정적으로 전속 양도된다.</p><h3 id="제4조-재하도급-전면-금지" tabindex="-1">제4조 (재하도급 전면 금지) <a class="header-anchor" href="#제4조-재하도급-전면-금지" aria-label="Permalink to “제4조 (재하도급 전면 금지)”">​</a></h3><p>&quot;을&quot;은 &quot;갑&quot;의 사전 서면 승인 없이 본 과업을 제3자에게 재하도급(재하청)할 수 없다.</p><h3 id="제5조-하자담보책임-back-to-back" tabindex="-1">제5조 (하자담보책임 - Back-to-Back) <a class="header-anchor" href="#제5조-하자담보책임-back-to-back" aria-label="Permalink to “제5조 (하자담보책임 - Back-to-Back)”">​</a></h3><p>&quot;을&quot;은 최종 검수 완료일로부터 1년간 납품 산출물의 결함에 대하여 무상으로 하자보수할 책임을 부담한다.</p><p>체결일자: 202 년 월 일 [갑] 주식회사 엠파시 대표이사 [ ] (인) [을] 주식회사 [협력사명] 대표이사 [ ] (인)</p>',13)])])}const d=t(l,[["render",c]]);export{u as __pageData,d as default};
